(() => {
  const CFG = window.__CFG;
  const S = window.__HQ = { id: CFG.id, state: "running", done: 0, total: CFG.items.length, errors: [] };
  const sleep = (() => { try {
    const w = new Worker(URL.createObjectURL(new Blob(["onmessage=e=>setTimeout(()=>postMessage(e.data[0]),e.data[1])"], { type: "text/javascript" })));
    let n = 0; const cb = new Map(); w.onmessage = e => { const f = cb.get(e.data); cb.delete(e.data); if (f) f(); };
    return ms => new Promise(r => { const id = ++n; cb.set(id, r); w.postMessage([id, ms]); });
  } catch (e) { return ms => new Promise(r => setTimeout(r, ms)); } })();
  let last = 0;
  const pause = async () => { const w = 2500 + Math.random() * 2000 - (Date.now() - last); if (w > 0) await sleep(w); };
  const ascii = s => s.replace(/[^\x00-\x7e]/g, c => "\\u" + ("000" + c.charCodeAt(0).toString(16)).slice(-4));
  const save = (id, arr) => localStorage.setItem("hqSweep:" + id, "HQBEGIN" + id + "|" + arr.length + "|" + ascii(JSON.stringify(arr)) + "HQEND");
  const CK = "hqSweep:" + CFG.id + "-ck";
  let resume = [];
  try { const c = JSON.parse(localStorage.getItem(CK)); if (c && Array.isArray(c.out)) resume = c.out; } catch (e) {}
  const get = async u => {
    await pause(); last = Date.now();
    const r = await fetch(u, { credentials: "same-origin" });
    if (r.status === 403 || r.status === 429) throw new Error("BLOCKED " + r.status);
    const t = await r.text();
    if (/captcha|are you a human/i.test(t.slice(0, 4000))) throw new Error("BLOCKED captcha");
    return { status: r.status, text: t };
  };
  const find = async it => {
    if (it.url) return it.url;
    const r = await get("/stingray/do/location-autocomplete?location=" + encodeURIComponent(it.q) + "&v=2");
    const p = JSON.parse(r.text.replace(/^\{\}&&/, "")).payload || {};
    const m = p.exactMatch || (p.sections && p.sections[0] && p.sections[0].rows && p.sections[0].rows[0]);
    if (!m || !m.url || !/\/home\//.test(m.url)) return null;
    const num = it.q.trim().split(/\s+/)[0], zip = (it.q.match(/\b\d{5}\b/) || [])[0];
    if (!String(m.name || "").startsWith(num) || (zip && !m.url.includes(zip))) return null;
    return m.url;
  };
  const pull = (html, url) => {
    const norm = html.replace(/\\u002F/g, "/").replace(/\\\//g, "/");
    const all = [...new Set(norm.match(/https:\/\/ssl\.cdn-redfin\.com\/photo\/\d+\/bigphoto\/[^"'\s\\)]+?\.jpg/g) || [])];
    const idOf = u => (u.match(/\/([^/]+?)_\d+(?:_\d+)?\.jpg$/) || [])[1];
    const count = {}; all.forEach(u => count[idOf(u)] = (count[idOf(u)] || 0) + 1);
    const best = Object.keys(count).sort((a, b) => count[b] - count[a])[0];
    const photos = all.filter(u => idOf(u) === best).slice(0, CFG.slim ? 40 : 999);
    const d = new DOMParser().parseFromString(html, "text/html");
    d.querySelectorAll("script,style,noscript").forEach(e => e.remove());
    const b = d.body.textContent.replace(/\s+/g, " ");
    const g = re => (b.match(re) || [])[1] || "";
    const at = b.search(/\d+ photos/);
    const head = b.slice(at < 0 ? 0 : at, (at < 0 ? 0 : at) + 400);
    const status = at < 0 ? "unknown" : /OFF MARKET|SOLD ON|SOLD [A-Z]{3}/i.test(head) || /This home is no longer for sale/i.test(b.slice(0, 20000)) ? "gone"
      : /Pending|Contingent|Under contract/i.test(head) ? "pending" : /for sale/i.test(head) ? "active" : "unknown";
    const facts = {};
    d.querySelectorAll("li, .entryItem").forEach(e => {
      const t = e.textContent.replace(/\s+/g, " ").trim();
      const m = t.match(/^([A-Z][A-Za-z#&/() -]{2,38}):\s*(.{1,150})$/);
      if (m && !facts[m[1]]) facts[m[1]] = m[2];
    });
    const pick = (...keys) => { for (const k of keys) for (const f in facts) if (f.toLowerCase().includes(k)) return facts[f]; return ""; };
    const rem = d.querySelector("#marketing-remarks-scroll");
    return {
      url, status, banner: head.slice(0, 120), photos,
      price: parseInt((head.match(/\$([\d,]{5,})/) || [])[1]?.replace(/,/g, "")) || null,
      statline: (head.match(/(\d+(?:\.\d+)?)bd\D+(\d+(?:\.\d+)?) ba\D+([\d,]+|—)sq ft/) || []).slice(1),
      yearBuilt: g(/(\d{4}) ?Year Built/), lot: g(/([\d.,]+ ?(?:sq ft|acres?)) ?Lot Size/i), ppsf: g(/(\$[\d,]+) ?Price\/Sq\.?Ft/i),
      mls: g(/MLS\s*#?\s*:?\s*([A-Z0-9-]{5,})/),
      taxes: pick("tax annual", "annual tax", "taxes"), heating: pick("heating"), cooling: pick("cooling"),
      parking: pick("garage spaces", "parking total", "parking"), basement: pick("basement"),
      remarks: rem ? rem.textContent.replace(/\s+/g, " ").trim().slice(0, CFG.slim ? 1500 : 3000) : "",
      ...(CFG.slim ? {} : { facts })
    };
  };
  (async () => {
    const out = resume.slice();
    S.done = out.length;
    try {
      for (const it of CFG.items.slice(out.length)) {
        const row = { key: it.key, q: it.q };
        try {
          const url = await find(it);
          if (!url) row.status = "no-listing";
          else {
            const r = await get(url);
            row.http = r.status;
            if (r.status === 404 || r.status === 410) row.status = "gone";
            else if (r.status !== 200) row.status = "unknown";
            else Object.assign(row, pull(r.text, url.startsWith("http") ? url : "https://www.redfin.com" + url));
          }
        } catch (e) {
          row.status = "error"; S.errors.push(it.key + ": " + e.message);
          if (/BLOCKED/.test(e.message)) { S.state = "blocked"; out.push(row); break; }
        }
        out.push(row); S.done++;
        try { localStorage.setItem(CK, JSON.stringify({ out })); } catch (e) { S.errors.push("checkpoint: " + e.message); }
      }
      save(CFG.id, out);
      if (S.state !== "blocked") localStorage.removeItem(CK);
      save(CFG.id + "-meta", [{ state: S.state === "running" ? "saved" : S.state, errors: S.errors }]);
      if (S.state === "running") S.state = "saved";
    } catch (e) { S.errors.push("fatal: " + e.message); S.state = "failed"; }
  })();
  return "started " + CFG.id;
})();
